insert into public.qcm_bank
  (bank_id, otr_number, module, chapter, context, star, corrected, stem, options, justification, sources)
values
(201, 18, 'Traumatologie', 'Amputations des membres', 'Cas clinique: « Un jeune, victime d’un accident de circulation (moto) survenu Il y a 4 mois, présentant une paralysie de l’abduction et l’antépulsion de l’épaule gauche, avec hypoesthésie du moignon de l’épaule gauche. Sans', true, true, 'Il s’agit (Cochez la ou les réponses justes);', '[{"l":"A","t":"De la paralysie du nerf axillaire (circonflexe).","c":true},{"l":"B","t":"De la paralysie du plexus brachial (C5 C6),","c":false},{"l":"C","t":"De la paralysie du nerf radial.","c":false},{"l":"D","t":"De la paralysie du nerf ulnaire (cubital)","c":false},{"l":"E","t":"De la paralysie du nerf fibulaire commun (SPE).","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(202, 18, 'Traumatologie', 'Amputations des membres', 'Cas clinique: « Un jeune, victime d’un accident de circulation (moto) survenu Il y a 4 mois, présentant une paralysie de l’abduction et l’antépulsion de l’épaule gauche, avec hypoesthésie du moignon de l’épaule gauche. Sans', true, true, 'Les muscles abducteurs de l’épaule selon le testing musculaire sont cotés à 2 (cocher la réponse juste).', '[{"l":"A","t":"Il s’agit d’une contraction musculaire permettant le mouvement en absence de pesanteur.","c":true},{"l":"B","t":"Il s’agit d’une contraction musculaire permettant de mouvement contre la pesanteur.","c":false},{"l":"C","t":"Il s’agit d’une contraction musculaire sans mouvement (ébauche).","c":false},{"l":"D","t":"Il s’agit d’une contraction musculaire permettant le mouvement contre une légère résistance.","c":false},{"l":"E","t":"Il s’agit d’une contraction musculaire permettant le mouvement contre une grande résistance.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(203, 32, 'Traumatologie', 'Ceinture scapulaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'Une complication est particulièrement fréquente: il s’agit', '[{"l":"A","t":"de la paralysie du nerf axillaire (circonflexe)","c":false},{"l":"B","t":"de la paralysie du plexus brachial","c":false},{"l":"C","t":"de la paralysie du nerf radial","c":true},{"l":"D","t":"de la paralysie du nerf ulnaire (Cubital)","c":false},{"l":"E","t":"de la paralysie du nerf fibulaire commun (SPE)","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(204, 32, 'Traumatologie', 'Ceinture scapulaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'Pour éliminer cette complication neurologique, il faut:', '[{"l":"A","t":"Tester les muscles releveurs de l’épaule.","c":false},{"l":"B","t":"vérifier l’intégrité du revêtement cutané","c":false},{"l":"C","t":"palper les pouls radial et cubital homolatéraux","c":false},{"l":"D","t":"tester les muscles releveurs (extenseurs) du poignet et de la main","c":true},{"l":"E","t":"faire radiographies de la main et du poignet","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(205, 32, 'Traumatologie', 'Fracture de l’humérus', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'L’intensité des signes cliniques dans le syndrome épaule-main est: (La RJ)', '[{"l":"A","t":"Indépendante de son étiologie.","c":false},{"l":"B","t":"Inversement proportionnelle l’importance du traumatisme de l’épaule.","c":false},{"l":"C","t":"Plus bruillante dans les étiologies neurologiques.","c":true},{"l":"D","t":"Très modérée en cas de luxation de l’épaule.","c":false},{"l":"E","t":"Touche plus le coude.","c":false},{"l":"A","t":"Sur le bilan biologie","c":false},{"l":"B","t":"Sur l’échographie des parties molles","c":false},{"l":"C","t":"Sur la scintigraphie osseuse","c":true},{"l":"D","t":"Sur la biopsie osseuse","c":false},{"l":"E","t":"Sur l’interrogatoire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(206, 32, 'Traumatologie', 'Ceinture scapulaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'Les formes les plus fréquentes d’AND sont localisés aux: (La ou les réponses justes)', '[{"l":"A","t":"syndrome épaule/main","c":true},{"l":"B","t":"rachis dorsal","c":false},{"l":"C","t":"pieds","c":true},{"l":"D","t":"mains","c":true},{"l":"E","t":"rachis lombaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(207, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'Le diagnostic clinique d’une luxation antérieure de l’épaule se base sur: La/Les RF', '[{"l":"A","t":"Signe de l’epaulette","c":false},{"l":"B","t":"Vacuite dela glene de l’omoplate","c":false},{"l":"C","t":"Position anormale dela tete humerale","c":false},{"l":"D","t":"L’abduction reductible du bras","c":true},{"l":"E","t":"LesignedeBerger","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(208, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'La luxation antéro-interne de l’épaule se caractérise par tous les signes suivants sauf un, lequel ?', '[{"l":"A","t":"L’abduction irreductible","c":false},{"l":"B","t":"L’ecchymosebrachio-thoracique","c":true},{"l":"C","t":"Le vide sous-acromial","c":false},{"l":"D","t":"Le coup de hache externe","c":false},{"l":"E","t":"Lecomblementdusillondelto-pectoral","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(209, 32, 'Traumatologie', 'Ceinture scapulaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'Le siège anatomique le plus fréquent des fractures de la clavicule se situe: La RJ', '[{"l":"A","t":"Au1/3interne","c":false},{"l":"B","t":"Au1/3moyen","c":true},{"l":"C","t":"Au1/4externe","c":false},{"l":"D","t":"Plaque coracoidienne","c":false},{"l":"E","t":"Zone d’insertionduligamentcosto-chondro-claviculaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(210, 32, 'Traumatologie', 'Ceinture scapulaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'Une luxation acromion claviculaire de stade III se définit par: La/Les RJ', '[{"l":"A","t":"Une lesion des ligaments conoides et trapezoides","c":true},{"l":"B","t":"Une lésion de la sangle musculaire deltoïdo- trapézoïdienne","c":true},{"l":"C","t":"Une lesion du ligament acromio-coracoïdien","c":false},{"l":"D","t":"Une lésion des moyens d’union intrinsèque de l’articulation acromio-claviculaire","c":true},{"l":"E","t":"Une atteinte des insertions claviculaires des petits et grands pectoraux","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(211, 32, 'Traumatologie', 'Ceinture scapulaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'Une fracture du tiers moyen de la clavicule: La RJ', '[{"l":"A","t":"Entraine souvent des lesions dela veine sous-clavière","c":false},{"l":"B","t":"Consolidee n moyenne en90jours","c":false},{"l":"C","t":"Laisse dans la regle un cal en baionnette exuberant","c":true},{"l":"D","t":"Relève d’une réduction anatomique avec une contention interne solide","c":false},{"l":"E","t":"Est traitee par un bandage coude au corps","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(212, 32, 'Traumatologie', 'Ceinture scapulaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'Une complication neurologique est particulièrement fréquente; dans les FR de la diaphyse humérale:', '[{"l":"A","t":"Paralysie d une rf(circonflexe).","c":false},{"l":"B","t":"Paralysie du plexus brachial.","c":false},{"l":"C","t":"Paralysie d une rf median.","c":false},{"l":"D","t":"Paralysie d une rf fibulaire.","c":false},{"l":"E","t":"Paralysie d une rf radial.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(213, 32, 'Traumatologie', 'Ceinture scapulaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'Four ce même patient le bilan radiologique doit comporter: La/Les RJ', '[{"l":"A","t":"Uneincidence3 ⁄4internedel’humérus","c":false},{"l":"B","t":"Uneincidence3 ⁄4externedel’humérus","c":false},{"l":"C","t":"Un profil axillaire de l’epaule","c":false},{"l":"D","t":"Une incidence de face de l’humerus","c":true},{"l":"E","t":"Une incidence de profil de l’humerus","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(214, 32, 'Traumatologie', 'Ceinture scapulaire', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'La paralysie sus citée se traduit cliniquement par:', '[{"l":"A","t":"Un deficit des extenseurs dela main","c":true},{"l":"B","t":"Uneanesthésiedelapulpedel’indexe","c":false},{"l":"C","t":"Une anesthésie de la face dorsale de la première commissure.","c":true},{"l":"D","t":"Un deficit des muscles interosseux dela main","c":false},{"l":"E","t":"Une anesthesie du moignon de l’epaule","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(215, 32, 'Traumatologie', 'Fracture de l’humérus', 'Cas clinique: « Un patient, victime d’un accident de la voie publique, et ramène aux urgences. L’examen clinique note une déformation douloureuse avec une tuméfaction du bras et évoquant une fracture de la diaphyse humérale. »', false, true, 'L’intensité des signes cliniques dans le syndrome épaule-main est: La RJ', '[{"l":"A","t":"Independante des on etiologie.","c":true},{"l":"B","t":"Inversement proportionnelle l’importance du traumatismedel’épaule.","c":false},{"l":"C","t":"Plusbruillantedanslesétiologiesneurologiques.","c":false},{"l":"D","t":"Tres moderee en cas de luxation de l’epaule.","c":false},{"l":"E","t":"Touche plus le coude.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(216, 20, 'Traumatologie', 'Ceinture scapulaire', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Les muscles de la coiffe des rotateurs: La/Les RJ', '[{"l":"A","t":"Ont un rôle de recentrage dynamique de l’articulation acromio-claviculaire.","c":false},{"l":"B","t":"Le supra épineux est le muscle le plus touché dans les tendinopathies dela coiffe.","c":true},{"l":"C","t":"Ledeltoideestunmusclepuissantdelacoiffe.","c":false},{"l":"D","t":"Les ous scapulaire est un rotateur interne.","c":true},{"l":"E","t":"La courte portion du biceps brachial fait partie de la coiffe des rotateurs.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(217, 20, 'Traumatologie', 'Épaule douloureuse (pathologie péri-articulaire)', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Concernant la bursite aiguë sous acromio- deltoïdienne: La/Les RF', '[{"l":"A","t":"Il s’agit d’une complication d’une tendinopathie calcifiante dela coiffe des rotateurs","c":false},{"l":"B","t":"Les mobilités active et passive de l’épaule sont conservées.","c":true},{"l":"C","t":"Le bilan radiographique est souvent normal","c":true},{"l":"D","t":"Une chondrocalcinose peut etre evoquee.","c":false},{"l":"E","t":"Le traitement medicales t toujours efficace.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(218, 32, 'Traumatologie', 'Fracture de l’humérus', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Quel est le mécanisme incriminé au cours d’une manœuvre de Neer positive ?', '[{"l":"A","t":"Une paralysie d une rf circonflexe","c":false},{"l":"B","t":"Une rupture du tendons upra epineux","c":false},{"l":"C","t":"Un conflit sous acromial","c":true},{"l":"D","t":"Une retraction ela capsule articulaire","c":false},{"l":"E","t":"Unebursiteaiguësousacromio-deltoïdienne.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(219, 18, 'Traumatologie', 'Amputations des membres', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Quel est le mécanisme incriminé au cours d’une épaule de pseudo-paralytique avec impossibilité de lever le bras passivement au-dessus de l’horizontale ?', '[{"l":"A","t":"Une paralyse d une rf circonflexe","c":false},{"l":"B","t":"Une rupture du tendon du supra epineux","c":true},{"l":"C","t":"Unconflitantéro-interne","c":false},{"l":"D","t":"Une retraction dela capsule articulaire","c":false},{"l":"E","t":"Unebursiteaiguësousacromio-deltoïdienne","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(220, 18, 'Traumatologie', 'Ceinture scapulaire', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Un jeune, victime d’un accident de circulation (moto) survenu Il y a 4 mois, présentant une paralysie de l’abduction et l’antépulsion de l’épaule gauche, avec hypoesthésie du moignon de l’épaule gauche. Sans aucune lésion osseuse (sur la Rx). Il s’agit:', '[{"l":"A","t":"Delaparalysiedunerfaxillaire(circonflexe).","c":true},{"l":"B","t":"Dela paralysie du plexus brachial(C5C6),","c":false},{"l":"C","t":"Delaparalysiedunerfradial.","c":false},{"l":"D","t":"Delaparalysiedunerfulnaire(cubital)","c":false},{"l":"E","t":"Delaparalysiedunerffibulairecommun(SPE).","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(221, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Indiquez parmi les suivants, les signes cliniques qui permettent d’affirmer l’existence d’une luxation acromio-claviculaire:', '[{"l":"A","t":"le signe de l’épaulette","c":false},{"l":"B","t":"un tiroir antérieur claviculaire","c":true},{"l":"C","t":"la mobilité de la clavicule en touche de piano","c":true},{"l":"D","t":"la douleur exquise à l’extrémité externe de la clavicule","c":true},{"l":"E","t":"le vide sous-acromial antérieur","c":false}]'::jsonb, NULL, '["Annales classées"]'::jsonb),
(222, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Parmi ces signes, quel(s) est(sont) celui(ceux) qui permet(tent) d’affirmer le diagnostic de la luxation antéro-Interne de l’épaule:', '[{"l":"A","t":"Un signe de l’épaulette","c":true},{"l":"B","t":"Un coup de hache externe","c":true},{"l":"C","t":"Un comblement du sillon pectoral","c":true},{"l":"D","t":"Une perte d’adduction de l’épaule","c":true},{"l":"E","t":"Une attitude vicieuse en rotation interne","c":false}]'::jsonb, 'Signe de l’épaulette (saillie de l’acromion) : juste. Coup de hache externe : juste. Comblement du sillon delto-pectoral : juste. Perte d’adduction : juste. Attitude en rotation interne : fausse (attitude irréductible en abduction et rotation externe, signe de Berger).', '["Annales classées"]'::jsonb),
(223, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'La luxation Erecta de l’épaule est une luxation:', '[{"l":"A","t":"Supérieure","c":false},{"l":"B","t":"Inférieure","c":true},{"l":"C","t":"Postérieure","c":false},{"l":"D","t":"antéro-interne sous-coracoidienne","c":false},{"l":"E","t":"antéro-interne coracoidienne","c":false}]'::jsonb, 'La luxation erecta est une luxation inférieure : la tête est sous la glène. Forme rare.', '["Annales classées"]'::jsonb),
(224, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Vous retrouvez lors d’un examen systématique régionale lors d’une luxation antéro-interne de l’épaule, une insensibilité à la piqure du moignon de l’épaule sur sa face externe. Vous évoquez alors une atteinte:', '[{"l":"A","t":"du nerf sus-scapulaire","c":false},{"l":"B","t":"de la racine C7 du plexus brachial","c":false},{"l":"C","t":"du nerf circonflexe","c":true},{"l":"D","t":"du nerf musculo-cutanné","c":false},{"l":"E","t":"de la branche superficielle du nerf spinal","c":false}]'::jsonb, 'L’insensibilité du moignon de l’épaule (face externe) évoque une atteinte du nerf circonflexe (anesthésie du moignon et paralysie du deltoïde).', '["Annales classées"]'::jsonb),
(225, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Quel est le signe clinique fondamental d’une luxation traumatique postérieure de l’épaule ?', '[{"l":"A","t":"Attitude du bras en adduction","c":false},{"l":"B","t":"Attitude du bras en rotation interne","c":true},{"l":"C","t":"Attitude du bras en rotation externe","c":false},{"l":"D","t":"Déformation du moignon de l’épaule","c":false},{"l":"E","t":"Aucun des signes précédents","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(226, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Quelle est la durée d’immobilisation d’une première luxation isolée de l’ épaule chez un adulte sans aucun antécédent ?', '[{"l":"A","t":"Moins de 15 jours","c":false},{"l":"B","t":"Entre trois et quatre semaines","c":true},{"l":"C","t":"Entre quatre et six semaines","c":false},{"l":"D","t":"Plus de 6 semaines","c":false},{"l":"E","t":"Plus de 2 mois","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(227, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'L’évolution d’une fracture de la clavicule vers la pseudarthrose:', '[{"l":"A","t":"Ne se voit jamais","c":false},{"l":"B","t":"Se voit surtout après traitement chirurgical","c":true},{"l":"C","t":"Ne se voit jamais après traitement orthopédique","c":false},{"l":"D","t":"Se voit surtout en l’absence de traitement","c":false},{"l":"E","t":"N’a pas de conséquence fonctionnelle","c":false}]'::jsonb, NULL, '["Banque de QCM OTR","Banque de QCM OTR p.18"]'::jsonb),
(228, 42, 'Traumatologie', 'Fracture de jambe ouverte et fermée', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Une fracture du 1/3 moyen de la clavicule au cours d’un traumatisme du thorax:', '[{"l":"A","t":"Entraîne souvent des lésions de la veine sous-clavière","c":false},{"l":"B","t":"Consolide en moyenne en 90 jours","c":false},{"l":"C","t":"Laisse dans la règle un gros cal en baïonnette","c":true},{"l":"D","t":"Relève d’une réduction anatomique avec une contention interne solide","c":false},{"l":"E","t":"Est traitée par un plâtre thoraco-brachial","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(229, 19, 'Traumatologie', 'Traumatismes de l’épaule : luxation de l’épaule ; disjonction acromio-claviculaire', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Parmi ces propositions concernant la luxation antérieure de l’épaule Cochez les réponses justes:', '[{"l":"A","t":"Lésion fréquente chez l’adulte jeune","c":true},{"l":"B","t":"Se complique très souvent de lésion du nerf circonflexe","c":false},{"l":"C","t":"Nécessite une réduction en urgence","c":true},{"l":"D","t":"Les récidives ne sont pas rares","c":true},{"l":"E","t":"Toutes les réponses sont justes","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(230, 32, 'Traumatologie', 'Ceinture scapulaire', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Une complication neurologique est particulièrement fréquente; dans les fractures de la diaphyse humérale:', '[{"l":"A","t":"Paralysie du nerf (circonflexe).","c":false},{"l":"B","t":"Paralysie du plexus brachial.","c":false},{"l":"C","t":"Paralysie du nerf médian.","c":false},{"l":"D","t":"Paralysie du nerf fibulaire.","c":false},{"l":"E","t":"Paralysie du nerf radial.","c":true}]'::jsonb, NULL, '["EMD OTR section B"]'::jsonb),
(231, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'La fracture de poteau-colles est caractérisée par:', '[{"l":"A","t":"Fracture a trait sus- articulaire","c":true},{"l":"B","t":"Fracture à déplacement postérieur","c":true},{"l":"C","t":"Du a un mécanisme en hyper flexion","c":false},{"l":"D","t":"Se manifeste par une déformation en ventre de fourchette","c":false},{"l":"E","t":"L’ouverture cutanée est fréquente.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(232, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'La fractura de pouteau-colles est caractérisée par (la ou les réponse(s) Juste(s))', '[{"l":"A","t":"Fracture a trait Intra articulaire","c":false},{"l":"B","t":"Fracture à déplacement antérieur","c":false},{"l":"C","t":"Du a un mécanisme en hyper extension","c":true},{"l":"D","t":"Se manifeste par une déformation en dos de fourchette","c":true},{"l":"E","t":"Le traitement est toujours chirurgical","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(233, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'Classiquement la fracture de Pouteau Colles succède à un traumatisme', '[{"l":"A","t":"En pronation forcée","c":false},{"l":"B","t":"???","c":false},{"l":"C","t":"De type ‘’coup de poing’’","c":false},{"l":"D","t":"Direct sur la face antérieure de l’avant-bras","c":false},{"l":"E","t":"En hyper-extension du poignet","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(234, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'Parmi les complications suivantes, laquelle (lesquelles) peut-on rencontrer au décours d’une fracture typique de Pouteau-Colles immobilisée pendant 45 jours ?', '[{"l":"A","t":"Pseudarthrose","c":false},{"l":"B","t":"Ossification péri articulaire","c":false},{"l":"C","t":"Syndrome du canal carpien","c":true},{"l":"D","t":"Algodystrophie","c":true},{"l":"E","t":"Nécrose post traumatique","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(235, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'La fracture de Pouteau colles: (la ou les RJs)', '[{"l":"A","t":"Fait suite à une chute en hyper flexion du poignet","c":false},{"l":"B","t":"Le trait de fracture est extra articulaire","c":true},{"l":"C","t":"Le déplacement fracturaire est postérieur","c":true},{"l":"D","t":"Le traitement peut être orthopédique","c":true},{"l":"E","t":"Fait suit toujours à un mécanisme direct","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(236, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, true, true, 'La fracture de Pouteau-Colles, cocher la ou les réponses fausses.', '[{"l":"A","t":"Est une fracture articulaire","c":true},{"l":"B","t":"Le déplacement fracturaire est postérieur","c":false},{"l":"C","t":"Due à un mécanisme indirect chute en hyper flexion.","c":true},{"l":"D","t":"Se manifeste par une déformation en ventre de fourchette.","c":true},{"l":"E","t":"Le traitement est toujours chirurgical.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(237, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'Concernant la fracture Pouteau-Colles: Cochez les réponses justes', '[{"l":"A","t":"caractérisé par une bascule antérieure du fragment distal","c":false},{"l":"B","t":"caractérisé par une bascule postérieure et une translation interne du fragment distal","c":false},{"l":"C","t":"caractérisé par une bascule postérieure et la translation externe du fragment distal","c":true},{"l":"D","t":"caractérisé par une bascule postérieure du fragment proximal","c":false},{"l":"E","t":"fréquente chez le sujet âgé ostéoporotique","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(238, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, true, true, 'La fracture du Pouteau-Colles est caractérisée par les signes suivants: cochez les réponses justes)', '[{"l":"A","t":"Déformation du poignet en dos de fourchette","c":true},{"l":"B","t":"Ascension de la styloïde radiale","c":true},{"l":"C","t":"Saillie interne de la styloïde cubitale","c":true},{"l":"D","t":"Point douloureux dorsal sous articulaire","c":false},{"l":"E","t":"Paresthésie dans le territoire du nerf médian","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(239, 29, 'Traumatologie', 'Algoneurodystrophie', NULL, false, true, 'Une fracture de l’extrémité du radius: (la ou les réponses justes)', '[{"l":"A","t":"Résulte le plus souvent d’une chute en hyper-flexion qu’en hyper-extension du poignet.","c":false},{"l":"B","t":"Se complique fréquemment d’une paralysie par compression du nerf médian.","c":false},{"l":"C","t":"Entraine dans sa forme typique, un déplacement postérieur et externe de l’épiphyse radiale.","c":true},{"l":"D","t":"Donne souvent des pseudarthroses.","c":false},{"l":"E","t":"Peut évoluer vers l’algodystrophie.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(240, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', NULL, false, true, 'Dans la fracture de Pouteau Colles: (cochez la ou les réponses justes)', '[{"l":"A","t":"Le poignet se déforme en dos de fourchette de face","c":false},{"l":"B","t":"Est définit par un trait sus-articulaire","c":true},{"l":"C","t":"Apanage du sujet âgé","c":true},{"l":"D","t":"La pseudarthrose est une complication fréquente","c":false},{"l":"E","t":"Caractérisé radiologiquement par une bascule antérieure et translation externe du fragment distal","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
