(259, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Cas Clinique: Vous recevez en consultation un malformation du membre supérieur bilatérale; La radiologie objective la même image de façon', false, true, 'La fracture de Pouteau-colles est: La/Les RJ', '[{"l":"A","t":"La fracture la plus rare des fractures de l’extremite inferieure dur adius","c":false},{"l":"B","t":"Elle s’accompagne d’un déplacement antérieur de laglèneradiale","c":false},{"l":"C","t":"La fracture est intra articulaire","c":false},{"l":"D","t":"Le traitement est peut etre orthopedique","c":true},{"l":"E","t":"Lafracturefaitsuiteàunechutesurlapaumedela main en hyper extension","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(260, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Cas Clinique: Vous recevez en consultation un malformation du membre supérieur bilatérale; La radiologie objective la même image de façon', false, true, 'La fracture de poteau-colles est caractérisée par:', '[{"l":"A","t":"Fracture a trait intra articulaire","c":false},{"l":"B","t":"Fracture ade place m ent anterieur","c":false},{"l":"C","t":"Duaunmécanismeenhyperextension","c":true},{"l":"D","t":"Se manifeste par une déformation en dos de fourchette","c":true},{"l":"E","t":"Le traitement est toujours chirurgical","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(261, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Cas Clinique: Vous recevez en consultation un malformation du membre supérieur bilatérale; La radiologie objective la même image de façon', false, true, 'La fracture de Pouteau colles: La/Les RJ', '[{"l":"A","t":"Fait suite a une chute en hyper flexion du poignet","c":false},{"l":"B","t":"Le trait de fracture est extra articulaire","c":true},{"l":"C","t":"Le deplacement fracturaire est posterieur","c":true},{"l":"D","t":"Le traitement peut etre orthopedique","c":true},{"l":"E","t":"Fait suit toujours aun mecanisme direct","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(262, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Cas Clinique: Vous recevez en consultation un malformation du membre supérieur bilatérale; La radiologie objective la même image de façon', false, true, 'La fracture de Pouteau-Colles: La/Les RF', '[{"l":"A","t":"Est une fracture articulaire","c":true},{"l":"B","t":"Le deplacement fracturaire est posterieur","c":false},{"l":"C","t":"Due aun mecanisme indirect chute en hyper flexion.","c":true},{"l":"D","t":"Se manifeste par une déformation en ventre de fourchette.","c":true},{"l":"E","t":"Le traitement est toujours chirurgical.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(263, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Un homme de 40 ans a eu un accident de circulation. Cet accident a conduit à devoir réaliser une amputation de membre inférieur à la jonction du tiers moyen-tiers supérieur de la jambe gauche. Dix jours après l’intervention le patient a été admis dans un service de rééducation', false, true, 'Dans un traumatisme du poignet, une fracture du scaphoïde peut présenter les signes suivants: La/Les RJ', '[{"l":"A","t":"Douleur provoquee ala palpation dela tabatiere anatomique.","c":true},{"l":"B","t":"Douleur ala flexion extension du pouce.","c":false},{"l":"C","t":"Impotence fonctionnelle relative du poignet.","c":true},{"l":"D","t":"Une déformation du poignet en ventre de fourchette.","c":false},{"l":"E","t":"Une radiographie du poignet de face et de profil normale.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","Annales classées","EMD OTR section A","EMD (section A) PROMO 2017"]'::jsonb),
(264, 38, 'Traumatologie', 'Coude, radius et avant-bras', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Les signes de la maladie amniotique: La/Les RJ', '[{"l":"A","t":"Polydactylies","c":false},{"l":"B","t":"Sillons","c":true},{"l":"C","t":"Amputations","c":true},{"l":"D","t":"Synostoses","c":false},{"l":"E","t":"Acrosyndactylies","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022","EMD OTR section A"]'::jsonb),
(265, 38, 'Traumatologie', 'Coude, radius et avant-bras', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Une éctromélie longitudinale latérale de l’avant-bras se défini par: La/Les RJ', '[{"l":"A","t":"Agénésieouhypoplasieduradius","c":true},{"l":"B","t":"Unepertedelaprono-suppination","c":false},{"l":"C","t":"Est la cause d’une main bote radiale","c":true},{"l":"D","t":"UntypeVdelaclassificationdeSWANSON","c":false},{"l":"E","t":"S’accompagne souvent d’une agénésie ou hypoplasiedupouce.","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(266, 38, 'Traumatologie', 'Coude, radius et avant-bras', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La synostose radio-ulnaire est: La RJ', '[{"l":"A","t":"Une ectromelie longitudinale laterale","c":false},{"l":"B","t":"Arret de developpement transversal","c":false},{"l":"C","t":"Arret de developpement longitudinal","c":false},{"l":"D","t":"Undéfautdeséparationlongitudinal","c":true},{"l":"E","t":"Undéfautdeséparationtransversal","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(267, 38, 'Traumatologie', 'Coude, radius et avant-bras', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Vous recevez en consultation un patient âgé de trois ans, présentant une malformation du membre supérieur bilatérale; La radiologie objective la même image de façon bilatérale. À savoir: - Quel est votre diagnostic à la radiographie ? La RJ', '[{"l":"A","t":"Hypo-plasiedurayonmédial","c":false},{"l":"B","t":"Hypo-plasiedurayonlatéral","c":false},{"l":"C","t":"Synostose radioulnaire","c":true},{"l":"D","t":"Agenesie des osdu carpe","c":false},{"l":"E","t":"Hypertrophie dur ayon medial","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(268, 38, 'Traumatologie', 'Coude, radius et avant-bras', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Quel(s) est (sont) le(s) mouvement(s) qui va (vont) être limité(s): La/Les RJ', '[{"l":"A","t":"Flexion du poignet","c":false},{"l":"B","t":"Flexion extension du coude","c":false},{"l":"C","t":"Inclinaison radiale","c":false},{"l":"D","t":"Pronation","c":true},{"l":"E","t":"Supination","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(269, 38, 'Traumatologie', 'Coude, radius et avant-bras', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'La synostose radio-ulnaire supérieure est:', '[{"l":"A","t":"Une fusion entre les2osdel’avant-bras au poignet","c":false},{"l":"B","t":"Une fusion entre les2osdel’avant-bras au coude","c":true},{"l":"C","t":"Un défaut de séparation longitudinale entre les deuxosdel’avant-bras","c":true},{"l":"D","t":"Un défaut de séparation transversale proximale entrelesdeuxdeosl’avant-bras","c":false},{"l":"E","t":"Responsable d’une limitation de flexion-extension ducoude","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(270, 15, 'Traumatologie', 'Coude, radius et avant-bras', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Parmi les fractures du membre supérieur, quelle sont celles qui se rencontrent fréquemment chez le sujet âgé ? (2 bonnes réponses)', '[{"l":"A","t":"La fracture supra-condylienne du coude","c":false},{"l":"B","t":"La fracture diaphysaire des deux os de l’avant-bras","c":false},{"l":"C","t":"La fracture métaphysaire inférieure du radius","c":false},{"l":"D","t":"La fracture du scaphoïde carpien","c":false},{"l":"E","t":"La fracture du col chirurgical de l’humérus","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(271, 25, 'Traumatologie', 'Fracture diaphysaire des deux os de l’avant-bras', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Lors d’un mouvement de défense, un individu reçoit un coup sur l’avant-bras. Le diagnostic de fracture de Monteggia est posé. Cela signifie pour vous:', '[{"l":"A","t":"Une fracture du radius avec luxation de la tête du cubitus (extrémité distale)","c":false},{"l":"B","t":"Une fracture distale du radius avec fracture proximale du cubitus","c":false},{"l":"C","t":"Une fracture du cubitus avec luxation de la tête du radius","c":true},{"l":"D","t":"Une fracture proximale du radius et du cubitus","c":false},{"l":"E","t":"Une fracture proximale du radius avec fracture distale du cubitus","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(272, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Un homme âgé de 50 ans, suite à une chute sur le verglas, a présenté une fracture métaphysaire inférieure du radius avec déplacement de type Goyrand-Smith. Cette fracture a été réduite sous anesthésie locorégionale et immobilisée à l’aide d’une attelle plâtrée maintenant le poignet en extension modéré Dans les jours qui suivent, il se plaint progressivement de douleurs dans les doigts et de dysesthésies. L’extension complète des doigts reste possible et peu douloureus Les symptômes sont plus marqués la nuit. Quel diagnostic évoquez-vous d’abord ?', '[{"l":"A","t":"Un syndrome de Volkman","c":false},{"l":"B","t":"Une névralgie cervico-brachiale favorisée par un étirement du plexus brachial","c":false},{"l":"C","t":"Une lésion nerveuse lors de l’anesthésie loco-régionale par infiltration du plexus brachial","c":false},{"l":"D","t":"Un syndrome du canal de Guyon","c":false},{"l":"E","t":"Un syndrome du canal carpien","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(273, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Classiquement la fracture de Pouteau-Colles succède à un traumatisme:', '[{"l":"A","t":"En pronation forcée","c":false},{"l":"B","t":"En flexion-adduction de la main","c":false},{"l":"C","t":"De type ‘coup de poing’","c":false},{"l":"D","t":"Direct sur la face antérieure de l’avant-bras","c":false},{"l":"E","t":"En hyperextension du poignet","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(274, 37, 'Traumatologie', 'Traumatismes osseux du genou', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Indiquez, parmi les suivantes, la(les) proposition(s) exacte(s) concernant la fracture de l’extrémité supérieure du radius de l’adulte:', '[{"l":"A","t":"Elle limite l’extension du coude","c":true},{"l":"B","t":"Elle peut être traitée par rééducation immédiate","c":true},{"l":"C","t":"Elle peut être traitée par résection de la tête radiale","c":true},{"l":"D","t":"Elle s’accompagne souvent d’une paralysie de la branche postérieure du nerf radial","c":false},{"l":"E","t":"Elle peut entraîner une raideur de la prono-supination","c":true}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(275, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'Un jeune garçon de 6ans présente depuis 6 heures, après contusion minime, de violentes douleurs du genou gauche. A l’examen: fièvre à 39°C, tachycardie, douleur fémorale métaphysaire inférieur, circulaire, réveillée a la palpation; mobilisation douce du genou possible; ongle incarné infecté du gros orteil gauche. Radiographie du genou de face et de profill: sans particularité. N.F: 15000 globules blancs, dont 80% de neutrophiles. V.S 60 à la 2ème heure et 80 à la 2eme heure et une CRP élevée.', false, true, 'Dans la fracture de Pouteau-Colles cochez la proposition fausse:', '[{"l":"A","t":"Il s’agit d’une fracture fréquente chez le sujet âgé","c":false},{"l":"B","t":"C’est une fracture extra articulaire","c":false},{"l":"C","t":"Caractérisée par une déformation en dos de fourchette de profil","c":false},{"l":"D","t":"Se complique souvent de pseudarthrose","c":true},{"l":"E","t":"Les propositions a, b et c sont justes","c":false}]'::jsonb, NULL, '["Banque de QCM OTR"]'::jsonb),
(276, 29, 'Traumatologie', 'Algoneurodystrophie', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, true, 'Les complications d’une fracture de l’extrémité intérieure de radius sont (Cocher la ou les réponses justes):', '[{"l":"A","t":"Le cal vicieux","c":true},{"l":"B","t":"jamais de déplacement secondaire","c":false},{"l":"C","t":"algodystrophie","c":true},{"l":"D","t":"osteonecrose E raideur du poignet","c":false}]'::jsonb, NULL, '["EMD section B promo 2019 (22/02/2024)"]'::jsonb),
(277, 15, 'Traumatologie', 'Traumatismes du poignet : fracture du poignet ; fracture des os du carpe', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, true, 'La fracture du scaphoïde carpien est (cocher la ou les réponses fausses):', '[{"l":"A","t":"Le diagnostic farg au stade de plaudarthrose","c":false},{"l":"B","t":"Une radio de poignet et pour diagnostic","c":true},{"l":"C","t":"L’évolution defavorabile pentaire vers farthrose du poignet.","c":false},{"l":"D","t":"en cas de trapnorthopédique le gant plat doit libérer la métacarpo-phalangienne du pouce","c":true},{"l":"E","t":"les fractures proxitalet doivent titre traitées chirurgicalement.","c":false}]'::jsonb, 'Correction reprise d’une question jumelle (même énoncé).', '["EMD section B promo 2019 (22/02/2024)","jumelle: Annales classées"]'::jsonb),
(278, 41, 'Traumatologie', 'Luxation du coude', 'EPREUVE THEORIQUE SECTION «B» Examen 5eme année unité appareil locomoteur', false, true, 'Le traitement d’une luxation postérieure du coude:', '[{"l":"A","t":"Doit se faire en urgence et sous anesthésie générale.","c":true},{"l":"B","t":"Est exclusivement chirurgical.","c":false},{"l":"C","t":"Par une simple écharpe après réduction orthopédique.","c":false},{"l":"D","t":"On pratique souvent une réparation ligamentaire par suture.","c":false},{"l":"E","t":"Réduction orthopédique par mancœuvre externe et immobilisation plâtrée par BABP.","c":true}]'::jsonb, NULL, '["Rattrapage OTR promo 2019"]'::jsonb),
(279, 43, 'Traumatologie', 'Main', NULL, true, true, 'Parmi les signes suivants un n’est jamais constaté à la période d’alarme de syndrome de Volkmann:', '[{"l":"A","t":"Paralysie du nerf médian.","c":false},{"l":"B","t":"Œdème des doigts.","c":false},{"l":"C","t":"Impotence douloureuse des doigts.","c":false},{"l":"D","t":"Abolition du pouls radial.","c":true},{"l":"E","t":"Rétraction irréductible des fléchisseurs de la main.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(280, 43, 'Traumatologie', 'Main', NULL, false, true, 'Quel(s) est (sont) le (les) signe(s) toujours constaté(s) à la période d’alarme du syndrome de Volkmann ?', '[{"l":"A","t":"Abolition du pouls radial","c":false},{"l":"B","t":"Impotence douloureuse des doigts","c":true},{"l":"C","t":"Œdème distal","c":true},{"l":"D","t":"Rétraction irréductible des fléchisseurs","c":false},{"l":"E","t":"Paralysie du nerf médian","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(281, 32, 'Traumatologie', 'Main', 'Cas clinique: « Un patient victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. »', false, true, 'Face à ce patient, il est impératif de: (cochez la ou les réponses justes)', '[{"l":"A","t":"Rechercher cliniquement d’autres lésions traumatiques.","c":true},{"l":"B","t":"De vérifier l’intégrité du revêtement cutané.","c":true},{"l":"C","t":"De tester les muscles fléchisseurs de la main.","c":false},{"l":"D","t":"De palper les pouls radial et cubital homolatéraux.","c":true},{"l":"E","t":"De faire une ponction de l’hématome fracturaire.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(282, 32, 'Traumatologie', 'Main', 'Cas clinique: « Un patient victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. »', false, true, 'On teste la fonction du fléchisseur commun superficiel lors d’une plaie de la main:', '[{"l":"A","t":"En demandant au sujet de fermer le poing","c":false},{"l":"B","t":"En immobilisant la paume fortement et en demandant de fléchir P1","c":false},{"l":"C","t":"En immobilisant P2 fortement et on demandant de fléchir P3","c":false},{"l":"D","t":"En immobilisant en extension les doigts voisins et en demandant la flexion du doigt","c":true},{"l":"E","t":"Aucune de ces propositions n’est exacte","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(283, 32, 'Traumatologie', 'Main', 'Cas clinique: « Un patient victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. »', false, true, 'On teste la fonction du fléchisseur commun profond lors d’une plaie de la main:', '[{"l":"A","t":"En demandant au sujet de fermer le poing","c":false},{"l":"B","t":"En immobilisant la paume fortement et en demandant de fléchir P1.","c":false},{"l":"C","t":"En immobilisant P2 fortement et en demandant de fléchir P3","c":true},{"l":"D","t":"En immobilisant P1 fortement et en demandant de fléchir P2","c":false},{"l":"E","t":"En immobilisant P3 fortement et en demandant de fléchir P1.","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
(284, 32, 'Traumatologie', 'Main', 'Cas clinique: « Un patient victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. »', false, true, 'Concernant les plaies de la main: la ou les RJ:', '[{"l":"A","t":"Une impossibilité de faire une flexion de l’articulation interphlangienne distale témoigne d’une lésion d’un fléchisseur profond","c":false},{"l":"B","t":"Une impossibilité de faire une flexion de l’articulation interphlangienne proximale témoigne d’une lésion d’un fléchisseur profond","c":true},{"l":"C","t":"Une plaie pénétrante sur un trajet nerveux sans déficit moteur ne nécessite pas une exploration chirurgicale","c":true},{"l":"D","t":"La rééducation n’est indispensable après réparation tendineuse","c":true},{"l":"E","t":"Une immobilisation plâtrée est toujours nécessaire après réparation tendineuse","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
