(288, 32, 'Traumatologie', 'Main', 'Cas clinique: « Un patient victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. »', false, true, 'On teste la fonction du fléchisseur commun superficiel lors d’une plaie de la main:', '[{"l":"A","t":"en demandant au sujet de fermer le poigné","c":false},{"l":"B","t":"en immobilisant la paume fortement et en demandant de réfléchir P1","c":false},{"l":"C","t":"en immobilisant P2 de fortement et en demandant de fléchir P3","c":false},{"l":"D","t":"en immobilisant P3 fortement et demandant de fléchir P2","c":true},{"l":"E","t":"aucune de ces propositions est exactes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(289, 32, 'Traumatologie', 'Main', 'Cas clinique: « Un patient victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. »', false, true, 'Indiqué parmi les suivants, les signes qui, en présence d’une plaie d’un doigt permette(ent) de reconnaître l’existence d’une section d’un nerf Collatéral:', '[{"l":"A","t":"extrémité digitale froide","c":false},{"l":"B","t":"absence de mobilité active en flexion du doigt","c":false},{"l":"C","t":"perte de la sensibilité d’une hémipulpe","c":true},{"l":"D","t":"perte de l’extension active de la 2ème et 3ème phalange","c":false},{"l":"E","t":"hyperesthésie pulpaire","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(290, 32, 'Traumatologie', 'Main', 'Cas clinique: « Un patient victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. »', false, true, 'A propos d’un panaris de la pulpe du pouce, la ou les proposition(s) suivante(s) est (sont) exactes:', '[{"l":"A","t":"Le Streptocoque est le germe pathogène habituel","c":false},{"l":"B","t":"Un panaris se traite par incision et non par excision","c":false},{"l":"C","t":"L’atrophie pulpaire cicatricielle est une des complications du panaris","c":true},{"l":"D","t":"La disposition anatomique de la gaine du fléchisseur du pouce permet une diffusion de l’infection jusqu’au poignet","c":true},{"l":"E","t":"Une lymphangite du membre supérieur avec adénopathie est fréquente au cours de l’évolution d’un panaris","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021"]'::jsonb),
(291, 32, 'Traumatologie', 'Main', 'Cas clinique: « Un patient victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. »', false, true, 'Indiquez, parmi les suivants, les signes les plus caractéristiques du phlegmon de la gaine des fléchisseurs du médius à un stade de début:', '[{"l":"A","t":"Douleur du dessus du poignet","c":false},{"l":"B","t":"Anesthésie du médius","c":false},{"l":"C","t":"Douleurs dans pli palmaire distal","c":true},{"l":"D","t":"Crochet irréductible","c":false},{"l":"E","t":"Cyanose du médius","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2021","Auto-évaluation OTR 2014-2022"]'::jsonb),
