(298, 32, 'Traumatologie', 'Main', 'Cas clinique: « Un patient victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. »', false, true, 'A propos d’une section d’un fléchisseur profond des doigts: La/Les RJ', '[{"l":"A","t":"Cette section supprime la flexion essentielle de P2 surP1.","c":false},{"l":"B","t":"La cicatrisation après suture est acquise en moyenneen6semaines","c":true},{"l":"C","t":"La principale séquelle d’une suture est une adherence cicatricielle ala gaine tendineuse","c":true},{"l":"D","t":"Après la suture, toute mobilisation du doigt est interdite jusqu’a cicatrisation complete","c":false},{"l":"E","t":"Lors d’une plaie antérolatérale rechercher une lesion d une rf collateral est systematique","c":true}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
(299, 32, 'Traumatologie', 'Main', 'Cas clinique: « Un patient victime d’un accident de la voie publique est ramené aux urgences, l’examen clinique note une déformation douloureuse avec une tuméfaction du bras évoquant une fracture de la diaphyse humérale. »', false, true, 'Une plaie de doigt en zone 1 avec déficit de flexion de P3 sur P2 est une: La RJ', '[{"l":"A","t":"Lésiondutendonfléchisseurcommunsuperficiel","c":false},{"l":"B","t":"Lesion du tendon flechisseur radial du carpe","c":false},{"l":"C","t":"Lesion du tendon flechisseur commun profond","c":true},{"l":"D","t":"Lesion du tendon flechisseur ulnaire du carpe.","c":false},{"l":"E","t":"Toutes les reponses sont justes","c":false}]'::jsonb, NULL, '["Auto-évaluation OTR 2014-2022"]'::jsonb),
